<?php
namespace App\Livewire;
use App\Models\SchoolSetting;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithFileUploads;
#[Layout('layouts.app')] class SchoolSettings extends Component {use WithFileUploads;public string $name='',$email='',$phone='',$address='',$motto='',$website='',$principal_name='';public $badge=null;public array $settings=[];protected array $keys=['receipt_footer','currency','number_format','admission_prefix','payment_methods','payment_receipt_email_enabled','mobile_money_details','bank_details','cash_pool_opening_balance','arrears_rule','term_closing_rule','payroll_approval_rule','academic_year_rule','grading_scale','promotion_rule','max_class_progression','required_student_fields','student_status_rules','staff_number_format','roles_permissions','payroll_period','leave_types','leave_approval_rule','sender_name','email_provider','sms_provider','arrears_email_template','notification_schedule','otp_enabled','audit_retention','backup_export_rule','timezone','date_format','language','certificate_title','certificate_subtitle','certificate_intro','certificate_achievement','certificate_signatory_name','certificate_signatory_title','certificate_number_prefix','recommendation_title','recommendation_intro','recommendation_body','recommendation_closing'];public function mount():void{$s=Auth::user()->school;foreach(['name','email','phone','address','motto','website','principal_name'] as $key)$this->{$key}=$s->{$key}??'';$stored=SchoolSetting::where('school_id',$s->id)->pluck('value','key')->all();foreach($this->keys as $key)$this->settings[$key]=$stored[$key]??$this->default($key);}protected function default(string $key):string{return match($key){'currency'=>'UGX','number_format'=>'1,234.56','payment_methods'=>'cash,mobile_money,bank','payment_receipt_email_enabled'=>'enabled','academic_year_rule'=>'Three terms per academic year','payroll_period'=>'Monthly','timezone'=>'Africa/Kampala','date_format'=>'d M Y','language'=>'English','otp_enabled'=>'enabled','certificate_title'=>'Certificate of Completion','certificate_subtitle'=>'Awarded with distinction and pride','certificate_intro'=>'This certificate is proudly presented to','certificate_achievement'=>'For successfully completing the prescribed course of study with dedication and commitment.','certificate_signatory_title'=>'Head Teacher','certificate_number_prefix'=>'CERT','recommendation_title'=>'Letter of Recommendation','recommendation_intro'=>'To Whom It May Concern','recommendation_body'=>'We are pleased to recommend this graduate, who completed their studies at our institution with commitment, discipline, and good standing.','recommendation_closing'=>'We confidently recommend them for further study and suitable opportunities.',default=>''};}public function save():void{$this->validate(['name'=>'required|string|max:255','email'=>'nullable|email','website'=>'nullable|url','badge'=>'nullable|image|max:2048']);$school=Auth::user()->school;$school->update(['name'=>$this->name,'email'=>$this->email?:null,'phone'=>$this->phone?:null,'address'=>$this->address?:null,'motto'=>$this->motto?:null,'website'=>$this->website?:null,'principal_name'=>$this->principal_name?:null,'badge_path'=>$this->badge?$this->badge->store('school-badges','public'):$school->badge_path]);foreach($this->keys as $key)SchoolSetting::updateOrCreate(['school_id'=>$school->id,'key'=>$key],['value'=>$this->settings[$key]??null]);session()->flash('status','System settings saved.');}public function render(){return view('livewire.school-settings',['pageTitle'=>'System Settings']);}}
